package com.nvv.mediadata.view.coreimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.material3.TopAppBarimport androidx.compose.material3.TopAppBarDefaultsimport androidx.compose.runtime.Composableimport com.nvv.mediadata.data.model.destination.Destination@OptIn(ExperimentalMaterial3Api::class)@Composablefun TopBar(	destination: Destination,){	when(destination.route){		Destination.HOME.route -> {			TopAppBar(				colors = TopAppBarDefaults.topAppBarColors(				),				title = {					Text("Home")				}			)		}		Destination.MOVIE.route -> {			TopAppBar(				colors = TopAppBarDefaults.topAppBarColors(				),				title = {					Text("Movies")				}			)		}		Destination.TV.route -> {			TopAppBar(				colors = TopAppBarDefaults.topAppBarColors(				),				title = {					Text("Series")				}			)		}		Destination.PROFILE.route -> {			TopAppBar(				colors = TopAppBarDefaults.topAppBarColors(				),				title = {					Text("Profile")				}			)		}	}}